catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	var cpf = newValue.replace(/\D/g, '');
	var message;

	// Se o usuário digitou mas saiu com menos de 11 dígitos
	if (cpf.length > 0 && cpf.length < 11) {
		g_form.setValue('cpf_solicitante', '');

		getMessage('cpf_incompleto_msg', function (msg) {
			// Substitui o parâmetro {0} pelo valor digitado
			message = msg.replace('{0}', newValue);
			g_form.showFieldMsg('cpf_solicitante', message, 'error', true);
		});
		return;
	}

	// Se atingiu 11 dígitos, valida no servidor via Script Include
	if (cpf.length === 11) {
		var ga = new GlideAjax('x_fub_fundbrad_ev.EVUtils');
		ga.addParam('sysparm_name', 'validarCPF');
		ga.addParam('sysparm_cpf', newValue);
		ga.getXMLAnswer(function (response) {
			if (response !== 'true') {
				g_form.setValue('cpf_solicitante', '');

				getMessage('cpf_invalido_msg', function (msg) {
					message = msg.replace('{0}', newValue);
					g_form.showFieldMsg('cpf_solicitante', message, 'error', true);
				});
			} else {
				g_form.hideFieldMsg('cpf_solicitante', true);
			}
		});
	}
}
